const handle=document.querySelector('#menu-handle'),items=document.querySelector('#menu-items');handle?.addEventListener('click',()=>{const on=handle.getAttribute('aria-expanded')!=='true';handle.setAttribute('aria-expanded',String(on));items.toggleAttribute('data-visible',on);});items?.addEventListener('click',event=>{if(event.target.closest('a')){handle.setAttribute('aria-expanded','false');items.removeAttribute('data-visible');}});
const entry=document.querySelector('#entry-note');if(entry?.showModal){let wait=Math.max(0,Number(entry.dataset.wait)||0);const close=document.querySelector('#dismiss-entry'),count=close.querySelector('span');const enable=()=>{close.disabled=false;close.textContent='关闭提示，继续浏览';};entry.addEventListener('cancel',e=>{if(wait>0)e.preventDefault();});close.addEventListener('click',()=>{if(wait===0)entry.close();});entry.showModal();if(wait===0)enable();else{const countdown=setInterval(()=>{wait--;count.textContent=String(wait);if(!wait){clearInterval(countdown);enable();}},1000);}}
const motionItems=document.querySelectorAll('.device-theatre,.media-mock,.document-scene');if('IntersectionObserver'in window){const visibility=new IntersectionObserver(records=>records.forEach(record=>record.target.toggleAttribute('data-paused',!record.isIntersecting)));motionItems.forEach(element=>visibility.observe(element));}document.addEventListener('visibilitychange',()=>document.documentElement.toggleAttribute('data-paused',document.hidden));
